-- dmap_object_gen_tag : type : view name : personacleaver
set search_path = pppt,oracle,dmap_extension,public;/* dmap converted statement start */
create or replace view "personacleaver"  ("idpersonal", "interpretacion", "interpretacion1", "interpretacion2", "nombre", "nombre1", "nombre2") as select personalinterpretacion.idpersonal,  interpretacion.interpretacion,  interpretacion_1.interpretacion as interpretacion1,  interpretacion_2.interpretacion as interpretacion2,  interpretacion.nombre,  interpretacion_1.nombre as nombre1,  interpretacion_2.nombre as nombre2  from ((personalinterpretacion left join interpretacion on personalinterpretacion.idinterpretacion1 = interpretacion.idinterpretacion) left join interpretacion interpretacion_1 on personalinterpretacion.idinterpretacion2 = interpretacion_1.idinterpretacion) left join interpretacion interpretacion_2 on personalinterpretacion.idinterpretacion3 = interpretacion_2.idinterpretacion where (((personalinterpretacion.idprueba)=7));/* dmap converted statement end */
